import {texEq as eq,inlineMath} from './math.js';
import {section,table as baseTable,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {shiftFrame,rotaryFrequencies,positionalBlock,apply2} from './position-model.js';
export const positionSections=[['order','Where order enters attention'],['clocks','Sinusoidal features: several phase scales'],['spectrum','Why logarithmic spacing and the base matter'],['rotate','RoPE rotates learned content'],['relative','Absolute rotations, relative interaction'],['rotation-lab','Move both positions together'],['implementation','Pair layouts, precision and cache offsets'],['extension','Extending context changes a distribution'],['scaling','Interpolation, base changes and nonuniform scaling'],['local-warp','Preserve local distance, compress distant distance'],['partial','Partial RoPE is a subspace choice'],['nope','NoPE is not position blindness'],['hybrid','Local order and global retrieval'],['group','A composition law unifies the mechanisms'],['generators','Read the generator, not only the name'],['generator-lab','Inspect rotation, decay and shear'],['alibi','Additive bias through augmented coordinates'],['stability','Algebraic validity is not numerical stability'],['practice','Ablate the positional contract'],['sources','Sources and connected notes']];
export const positionMeta={slug:'models/position',title:'Positional Encodings',description:'Sinusoidal scales, relative RoPE geometry, context extension, NoPE hybrids and translation generators—with cache and stability conditions.',date:'2026-04-08',updated:'2026-10-14',topicPath:['models','representations'],tags:['position','RoPE','NoPE','ALiBi','YaRN','ReRoPE','GRAPE','generator','sinusoidal','context extension'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Derive relative rotary interactions and implement their offsets','Separate phase scaling from context capability','Classify positional dynamics under explicit composition assumptions'],related:['models/attention','training/parallelism','models/tokenization']};
export const positionAliases=['positional-encoding-sinusoidal-to-rope','rope-scaling','no-positional-embeddings-nope','group-theoretic-positional-encodings'].map(s=>'ai/architectures/transformers/'+s);
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"','class="dense-table-wrap" tabindex="0" role="region" aria-label="'+caption+'"').replace('<table>','<table style="min-width:640px">');
function spectrumRows(base){return rotaryFrequencies(8,base).map((w,i)=>`<tr><td>${i}</td><td>${(2*i/8).toFixed(2)}</td><td>${w.toPrecision(4)}</td><td>${(2*Math.PI/w).toFixed(1)}</td></tr>`).join('');}
function clockSvg(f){const point=v=>[150+110*v[0],150-110*v[1]];const q=point(f.q),k=point(f.k);return `<circle cx="150" cy="150" r="110" fill="none" stroke="#806278"/><path d="M30 150H270 M150 30V270" stroke="#53404f"/><line x1="150" y1="150" x2="${q[0]}" y2="${q[1]}" stroke="#bad6fa" stroke-width="5"/><circle cx="${q[0]}" cy="${q[1]}" r="7" fill="#bad6fa"/><line x1="150" y1="150" x2="${k[0]}" y2="${k[1]}" stroke="#bd738e" stroke-width="4" stroke-dasharray="8 4"/><circle cx="${k[0]}" cy="${k[1]}" r="7" fill="#bd738e"/>`;}
const rotationLab=`<div id="rotation-lab" class="topic-scene" data-rotation-lab><h3>Change the origin, keep the interaction</h3><p>Both unrotated content vectors are fixed at [1,0]. Query starts at m=2; key starts at n=5. A common shift moves both.</p><label>Common position shift <output data-shift>0.0</output><input type="range" min="0" max="100" step="1" value="0" aria-label="Common rotary position shift"></label><label>Frequency ω <select aria-label="Rotary angular frequency"><option value="0.2">0.2 rad/token</option><option value="0.4" selected>0.4 rad/token</option><option value="1">1 rad/token</option></select></label><div class="position-clock-layout"><svg viewBox="0 0 300 300" role="img" aria-label="Query and key rotate together while their angular gap remains fixed">${clockSvg(shiftFrame(0))}</svg><div><p>Solid baby blue: query Q<br>Dashed burgundy: key K</p><div class="scene-stats"><span>m <output data-m>2.0</output></span><span>n <output data-n>5.0</output></span><span>n−m <output>3</output></span><span>Q·K <output data-score>0.362358</output></span></div><p data-rotation-caption>Relative phase 1.200 rad. Dot product stays cos(1.200), despite the common shift.</p></div></div><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Synthetic single-pair geometry. Changing frequency changes the score; shifting both positions at a fixed frequency does not. Real Q/K also carry content. This unmasked pair illustrates the algebra; a causal query at m=2 cannot attend to a future key at n=5.</p></div>`;
const generatorLab=`<div id="generator-lab" class="topic-scene" data-generator-lab><h3>Apply one rule over a signed displacement</h3><p>Fixed input [0,1]. The causal age convention uses a≥0. Negative values expose the inverse transformation, not allowed future keys.</p><label>Generator family <select aria-label="Positional generator family"><option value="identity">NoPE / identity</option><option value="rotation" selected>Rotation</option><option value="decay">Exponential decay</option><option value="damped">Damped rotation</option><option value="jordan">Jordan shear</option></select></label><label>Displacement a <output data-age>5</output><input type="range" min="-20" max="20" step="1" value="5" aria-label="Generator displacement"></label><div class="scene-stats"><span>Output <output data-block-output>[-0.909, −0.416]</output></span><span>Norm <output data-block-norm>1.000</output></span></div><p data-block-caption>Rotation preserves norm in both directions.</p><p class="topic-scenes-caption">ω=.4, λ=.1. Exact closed-form toy blocks, not trained attention or an empirical extrapolation curve.</p></div>`;
export function positionReader(link){return topic(positionMeta,positionSections,'Position is a rule for changing an interaction—not a guarantee of long-context understanding.',`
<p>Attention compares content vectors. A positional mechanism changes what that comparison means when the same content appears elsewhere. The first design question is what should stay invariant: absolute location, relative distance, order or recency.</p><p>These choices are connected but distinct. Sinusoidal features expose several positional scales. RoPE applies those phases to queries and keys. Scaling changes the phases seen by a pretrained model. NoPE removes the explicit operation, while masks and recurrent dynamics can still convey order. Translation generators explain which linear dynamics compose consistently.</p>
${section('order','Where order enters attention',`<p>Unmasked self-attention without positional signals is permutation-equivariant. Reordering input tokens reorders output tokens in the same way. The operation cannot distinguish arrangements through an intrinsic index.</p>${eq(String.raw`\begin{aligned}h_p&=E(x_p)+\operatorname{PE}(p)\\\operatorname{Attention}(Q,K,V)&=\operatorname{softmax}\!\left(\frac{QK^\top}{\sqrt{d_h}}+M_{\mathrm{causal}}\right)V\end{aligned}`,'E maps tokens to vectors. A causal mask restricts visibility; it is not an added positional vector.')}
<p>A causal decoder is different from an unmasked encoder. Position i sees only its prefix. Different prefix lengths create a graph asymmetry that later layers may exploit. Explicit encoding supplies a direct bias rather than requiring the network to infer every positional relation.</p>`)}
${section('clocks','Sinusoidal features: several phase scales',`${eq(String.raw`\begin{aligned}\operatorname{PE}(p)_{2i}&=\sin(p\omega_i)\\\operatorname{PE}(p)_{2i+1}&=\cos(p\omega_i)\\\omega_i&=b^{-2i/d},\quad i=0,\ldots,\tfrac d2-1\end{aligned}`,'The 2017 Transformer uses b=10,000 and embedding width d=dmodel. One frequency consumes two dimensions.')}
<p>One sine value is ambiguous: sin(30°)=sin(150°)=.5. The paired cosine values differ, .866 versus −.866. Together they locate a point on a circle. Sine-first and cosine-first layouts are conventions; use one consistently.</p><p>Every pair has a period ${inlineMath(String.raw`\frac{2\pi}{\omega}`)}. Faster pairs resolve fine changes. Slower pairs change over longer spans. Many distinct phases give more useful scales than repeated copies of one clock. Repeated frequencies are permitted, but reduce frequency diversity.</p>${eq(String.raw`\begin{aligned}u_\omega(p)&=[\cos(p\omega),\sin(p\omega)]^\top\\u_\omega(p+r)&=R(r\omega)u_\omega(p)\\u_\omega(p)^\top u_\omega(q)&=\cos((p-q)\omega)\end{aligned}`,'A displacement acts through the same linear map wherever it begins. The complete positional dot product sums cosine terms across frequencies.')}
<p>The model need not reconstruct an integer position from these features. It can exploit their structured changes directly. Periodic pairs and finite precision do not provide a guaranteed unique integer code over arbitrary lengths.</p>`)}
${section('spectrum','Why logarithmic spacing and the base matter',`<p>The normalized exponent ${inlineMath(String.raw`\frac{2i}{d}`)} distributes pair indices over a logarithmic frequency range. At d=8 and b=10,000, frequencies are [1,.1,.01,.001]. Their denominators are [1,10,100,1000]. Without normalization, exponents 2i would make almost every pair nearly static.</p><p>A larger base lowers frequencies with ${inlineMath(String.raw`i>0`)}. It does not change the first frequency, ${inlineMath(String.raw`\omega_0=1`)}. Very slow pairs may contribute little variation over short training spans. The base is a spectrum parameter, not a fundamental constant or a maximum context length.</p><div class="topic-scene" data-spectrum-lab><h3>Change the spectrum, not the number of dimensions</h3><p>Rotary width stays eight. Period is measured in token positions.</p><label>Base b <select aria-label="Rotary base"><option value="10000">10,000</option><option value="500000">500,000</option><option value="1000000">1,000,000</option></select></label><div class="dense-table-wrap" tabindex="0" role="region" aria-label="Four pair frequencies"><table style="min-width:640px"><caption>Four pair frequencies</caption><thead><tr><th>Pair i</th><th>2i/d</th><th>ωᵢ</th><th>Period 2π/ωᵢ</th></tr></thead><tbody data-spectrum-rows>${spectrumRows(10000)}</tbody></table></div></div><p>At large width with b=10,000, the slowest frequency approaches 10⁻⁴. The exact last frequency is ${inlineMath(String.raw`b^{-1+\frac{2}{d}}`)}, not exactly ${inlineMath(String.raw`\frac1b`)}. Log spacing covers several orders of magnitude; it does not prove that the model uses every pair effectively.</p>`)}
${section('rotate','RoPE rotates learned content',`<p>Additive sinusoidal encoding constructs a vector and adds it to a token representation. Rotary Position Embedding instead rotates pairs in the projected query and key. Standard RoPE leaves values unrotated.</p>${eq(String.raw`\begin{aligned}R(\theta)&=\begin{bmatrix}\cos\theta&-\sin\theta\\\sin\theta&\cos\theta\end{bmatrix}\\R(\theta)\begin{bmatrix}x_0\\x_1\end{bmatrix}&=\begin{bmatrix}x_0\cos\theta-x_1\sin\theta\\x_0\sin\theta+x_1\cos\theta\end{bmatrix}\\Q_m&=R(m\omega)q_m,\quad K_n=R(n\omega)k_n\end{aligned}`,'R acts on one pair; in the partial-subspace equation it denotes the corresponding block-diagonal rotation. Apply independently to every rotary pair. A rotation preserves each pair’s norm and has inverse R(−θ).')}
<p>The learned content vector is not replaced with a position vector. Its orientation changes. The rotary spectrum uses the head's rotary width, which may differ from the embedding width used by additive PE.</p>`)}
${section('relative','Absolute rotations, relative interaction',`${eq(String.raw`\begin{aligned}Q_m^\top K_n&=q_m^\top R(m\omega)^\top R(n\omega)k_n\\&=q_m^\top R((n-m)\omega)k_n\end{aligned}`,'Transpose reverses a rotation. Multiplication adds angles. The same frequency must be used for the matched query/key pair.')}
<p>Absolute positions m and n cancel into a relative displacement in the positional operator. The entire score is not a function only of distance: q and k still carry content, including contextual information from earlier layers.</p><p>Hold unrotated q and k fixed. Shifting both positions by c preserves this pair's score. Shifting only the key changes the relative angle. This local algebraic identity does not prove that reprocessing a full model at a new context produces unchanged hidden states.</p>${rotationLab}`)}
${section('implementation','Pair layouts, precision and cache offsets',`<p>Use two separate operations: construct phase tables, then rotate adjacent feature pairs. The following callable reference uses PyTorch, not a fused kernel.</p><pre tabindex="0" role="region" aria-label="RoPE table construction"><code>import math
import torch

def rope_frequencies(sequence_length, head_dim, base=10_000.0,
                     device=None, offset=0):
    if head_dim &lt; 2 or head_dim % 2 or sequence_length &lt; 0:
        raise ValueError("nonnegative length and positive even width required")
    if not math.isfinite(base) or base &lt;= 1:
        raise ValueError("finite base greater than one required")
    pairs = torch.arange(0, head_dim, 2, device=device, dtype=torch.float32)
    positions = torch.arange(sequence_length, device=device, dtype=torch.float32) + offset
    angles = positions[:, None] * (base ** (-pairs / head_dim))[None, :]
    return angles.cos(), angles.sin()</code></pre><p>The tables have shape [sequence, head_dim/2]. Supply integer sequence length, rotary width and offset. Here head_dim means the even rotary width, not necessarily the full head width. Offset is the absolute index of the first supplied position.</p><pre tabindex="0" role="region" aria-label="Interleaved RoPE application"><code>def apply_rope(x, cos, sin):
    if x.shape[-1] % 2 or cos.shape != sin.shape:
        raise ValueError("even width and matching phase tables required")
    if cos.shape[-1] != x.shape[-1] // 2:
        raise ValueError("one phase per feature pair required")
    even, odd = x.float()[..., 0::2], x.float()[..., 1::2]
    c, s = cos.float(), sin.float()
    pairs = torch.stack((even*c - odd*s, even*s + odd*c), dim=-1)
    return pairs.flatten(start_dim=-2).to(x.dtype)</code></pre><p>Use floating-point Q and K shaped [batch, heads, sequence, rotary_width]. Add two leading singleton dimensions to the tables. GQA permits different query and key head counts. Keep the same batch, sequence positions, device and rotary width; the phase tables broadcast across heads.</p><pre tabindex="0" role="region" aria-label="Apply matching query and key phases"><code>cos, sin = rope_frequencies(q.shape[-2], q.shape[-1], device=q.device, offset=offset)
cos, sin = cos[None, None], sin[None, None]
q = apply_rope(q, cos, sin)
k = apply_rope(k, cos, sin)</code></pre><p>Concatenate any unrotated subspace separately. This reference is CPU-checked with float32, float16 and bfloat16 tensors. It is not a fused-kernel performance example or a GPU validation.</p><p>A split-half implementation pairs the first and second halves instead of adjacent dimensions. The weight layout, checkpoint convention and frequency tables must agree. Changing pairing alone does not preserve a trained checkpoint.</p><p>Compute phases with adequate precision before casting. Long positions can lose phase resolution in low-precision multiplication. Cache offsets must use the actual absolute position of each new key. Repeatedly rotating already-rotated cached keys creates an error.</p><p>Changing the base or scaling rule mid-sequence makes new queries inconsistent with stored rotated keys. Invalidate/rebuild the affected cache or use an implementation that stores enough unrotated information to recompute it. A fused kernel may apply rotations internally; test that path too.</p>`)}
${section('extension','Extending context changes a distribution',`<p>RoPE can compute an angle for any index. This mathematical ability is not a learned ability to retrieve or reason at that index. Longer contexts expose new relative phases, more competing keys, unfamiliar data and different numerical regimes.</p><p>Interpolation changes phase geometry. Continued training adapts the weights. Attention span and KV design determine cost. Evaluate these axes separately.</p><p>The Llama 3 report uses b=500,000, compared with the older 10,000 convention. Its 128k capability also uses staged long-context pretraining from 8k, not only that base change. A numeric base is not a certificate of a supported context window.</p><p>NoPE removes rotary phase extrapolation, but not attention dilution or unfamiliar long-document reasoning. A needle retrieval score is useful evidence for retrieval, not a complete measure of context use.</p>`)}
${section('scaling','Interpolation, base changes and nonuniform scaling',`${table('What each extension changes',['Approach','Effective phases','Main tradeoff'],[['Direct extrapolation',inlineMath(String.raw`m\omega_i`)+" with unchanged frequencies",'Preserves nearby phase differences; exposes unseen longer distances'],['Position interpolation',inlineMath(String.raw`\dfrac{m}{s}\omega_i`)+", "+inlineMath(String.raw`s=\dfrac{L_{\mathrm{target}}}{L_{\mathrm{train}}}`),'Returns phases to a shorter range; compresses all distances'],['Adjusted base frequency (ABF)',inlineMath(String.raw`m\,b_{\mathrm{new}}^{-2i/d}`),'Nonuniform frequency change; requires short/long evaluation'],['YaRN-style scaling','Different scaling across frequency ranges','Retains some local/high-frequency behavior; recipe and magnitude adjustments matter'],['LongRoPE','Nonuniform searched scaling and adaptation','Configuration/training procedure matter, not only a target length']])}
<p>Uniform interpolation maps positions from an extended interval into the old interval. It also scales a one-token gap to 1/s. Lower-frequency interpolation with higher frequencies retained can reduce this local distortion. These are tradeoffs, not universal winners.</p>${eq(String.raw`\beta=b^{2/d},\qquad\omega_i=\beta^{-i}`,'The base-β analogy treats pairs as positional scales. It is not literal digit extraction or a theorem that b≥L guarantees good extrapolation.')}
<p>In an integer numeral analogy, d/2 digits would span ${inlineMath(String.raw`\beta^{d/2}-1=b-1`)}. Rotary pairs are continuous phases, not extracted digits. This expression is not the maximum uniquely represented token index. The rough heuristic b≳L must not become a context guarantee.</p><p>High frequencies resemble low-order digits: they resolve small changes. Lower frequencies resemble high-order digits: they vary over longer spans. Uniform interpolation stretches every scale; changing the base leaves the first pair unchanged and stretches later pairs differently.</p><p>The Smol playbook's recorded ABF stages use about 2M for 4k→32k and 5M for 32k→64k. About 10M improved some long-context scores while hurting some short tasks. Its YaRN extension from 64k to 128k was more effective than to 256k. These are recipe-specific observations, not default values for every model.</p><p>Use adaptation data when the desired context is far outside training. Validate short-context recovery as well as long-context retrieval. Scaling only a frequency table does not reduce the memory or compute of full attention.</p>`)}
${section('local-warp','Preserve local distance, compress distant distance',`${eq(String.raw`\begin{aligned}r&=|n-m|\\f(r)&=\begin{cases}r,&r\le w\\w+\dfrac{r-w}s,&r>w\end{cases}\\\widetilde\Delta&=\operatorname{sign}(n-m)\,f(|n-m|)\end{aligned}`,'Take w≥0 and s≥1. This is a ReRoPE-inspired local/distant illustration, not the exact production ReRoPE operator or kernel recipe.')}
<p>With window w=4 and factor s=2, distance 3 stays 3, while distance 10 becomes 7. A negative displacement keeps its sign. The aim is clear: retain local geometry while coarsening long distances.</p><p>A nonlinear relative warp generally cannot be written as independently rotating every token at one linear absolute position. It need not satisfy f(a+b)=f(a)+f(b). Do not replace standard cached RoPE tables with this formula and assume the same efficient kernel remains valid.</p><p>The original ReRoPE series explores rectified relative treatment. Check the actual method, mask and attention implementation before reproducing it. The simple piecewise expression explains a design goal; it is not an implementation specification.</p>`)}
${section('partial','Partial RoPE is a subspace choice',`${eq(String.raw`\begin{aligned}q&=[q_{\mathrm{rope}},q_{\mathrm{content}}],\quad k=[k_{\mathrm{rope}},k_{\mathrm{content}}]\\\operatorname{score}&=q_{\mathrm{rope}}^\top R(n-m)k_{\mathrm{rope}}\\&\quad+q_{\mathrm{content}}^\top k_{\mathrm{content}}\end{aligned}`,'Rotate an even number of dimensions. State the rotary fraction and the denominator used to construct its frequencies.')}
<p>Partial RoPE mixes position-sensitive and unrotated content subspaces within one head. MLA uses a decoupled rotary subspace for compatibility with latent KV caching. Neither arrangement is a fully NoPE layer.</p><p>Gemma 4's recorded recipe uses p=.25 and base 1M in global layers, with full RoPE and base 10k locally. Its reported 37.5% global-cache saving also uses key-as-value attention. Merely skipping rotations on some dimensions does not shrink a conventional full K+V cache.</p><p><a href="${link('models/attention')}">Attention →</a> covers MLA and key-as-value storage. Keep their memory reductions separate from a positional subspace's purpose.</p>`)}
${section('nope','NoPE is not position blindness',`<p>NoPE omits added position vectors, Q/K rotations, relative bias tables and distance slopes. It does not change the ${inlineMath(String.raw`\dfrac{QK^\top}{\sqrt{d_h}}`)} attention operator. A causal mask still distinguishes visible prefixes.</p>${table('Evidence comes from different settings',['Work','Observation and scope'],[['Haviv et al., 2022','Competitive tested causal language models; probes recover increasingly useful absolute-position information'],['Kazemnejad et al., 2023','Strong length generalization on controlled reasoning/math tasks; theoretical absolute/relative functions and learned T5-like patterns'],['Yang et al., 2025','Pure NoPE improves retrieval behavior but can lose ordinary quality; hybrids separate local and global roles']])}
<p>These results do not prove pure NoPE wins at every scale. A bidirectional encoder lacks the same prefix asymmetry. Padding and packed-document boundaries change cues. Learned implicit position consumes capacity and depends on optimization.</p><p>Full NoPE retains O(L²) attention and the same projection-sized KV cache. Removing RoPE from pretrained weights is an architectural intervention, not a harmless decoding switch. Continue training or validate the intervention rigorously.</p>`)}
${section('hybrid','Local order and global retrieval',`<p>RoPE sliding-window layers can specialize in recent order-sensitive mixing. Global NoPE layers can retrieve by content without directly rotating similarity by relative distance. The useful division depends on span, data and training, not the names alone.</p><div class="dense-flow" role="img" aria-label="Three local rotary layers followed by one global NoPE layer"><div>Local RoPE</div><span>→</span><div>Local RoPE</div><span>→</span><div>Local RoPE</div><span>→</span><div>Global NoPE</div></div><p>RNoPE-SWA repeats three local RoPE layers and one global NoPE layer, with a recorded local window of 4,096. The final 8B comparison uses 5T pretraining tokens and staged 8k→32k→128k extension. The earlier three-way RoPE/NoPE/QK-Norm observation experiment uses 750B tokens; do not merge their budgets.</p><p>MAI-Thinking-1 records five local RoPE layers then one global NoPE layer. Kimi K3's no-embedding design also relies on KDA recurrent decay for recency. NoPE with a recurrent state is not identical to NoPE inside a window/full-attention stack.</p><p>Qiao et al. study efficient/full-attention hybrids and report that full-attention layers carry much long-range retrieval. Their experiments favor NoPE in those layers with limited short-context degradation. This supports an ablation, not a universal placement rule.</p><pre tabindex="0" role="region" aria-label="Local and global layer policy sketch"><code>is_global = (layer_index + 1) % 4 == 0
use_rope = not is_global
window = None if is_global else 4096
# Retain causal and document masks in BOTH layer types.</code></pre><h3 id="nope-code">Change the positional operation, not the attention contract</h3><p>This evaluation reference calls the two RoPE functions above. Use equal query/key/value head counts and compatible floating-point tensors. GQA needs a separately validated head-grouping path.</p><pre tabindex="0" role="region" aria-label="RoPE or NoPE attention reference"><code>def positional_attention(q, k, v, *, use_rope=True,
                         cos=None, sin=None, attn_mask=None):
    if attn_mask is None and q.shape[-2] != k.shape[-2]:
        raise ValueError("cached decode requires an explicit position mask")
    if use_rope:
        if q.shape[-2] != k.shape[-2]:
            raise ValueError("this reference needs matching rotary positions")
        if cos is None or sin is None:
            raise ValueError("RoPE requires phase tables")
        q, k = apply_rope(q, cos, sin), apply_rope(k, cos, sin)
    return torch.nn.functional.scaled_dot_product_attention(
        q, k, v, attn_mask=attn_mask, dropout_p=0.0,
        is_causal=attn_mask is None)</code></pre><p>For square uncached self-attention, the default supplies a causal triangle. An explicit mask must include every required causal, document and local-window restriction. In PyTorch SDPA, a boolean True permits attention. A supplied mask replaces the default triangle here.</p><p>Cached queries and keys can have different lengths and absolute offsets. Build their visibility mask from those positions; an upper-left triangle is not a general decode mask. The NoPE branch supports this with an explicit mask. The rotary branch assumes matching Q/K positions; general cached RoPE needs separate query/key phase arguments. The reference disables dropout for evaluation; training must select its own dropout probability.</p><p>These mask and dropout rules follow the ${cite('https://docs.pytorch.org/docs/2.14/generated/torch.nn.functional.scaled_dot_product_attention.html','PyTorch SDPA contract')}. The reference is CPU-checked against explicit masked attention, not validated as a fused GPU path.</p><p>When Q/K enter a NoPE layer, they must actually be unrotated. Keep correct cache-causal masking even when no rotary offsets are needed. Fused code must not silently reintroduce RoPE.</p>`)}
${section('group','A composition law unifies the mechanisms',`<p>Now ask which linear position transformations behave consistently under repeated shifts. Let F(s) transform a query and G(t) a key. Their score contains F(s)ᵀG(t). Require the positional operator to depend only on displacement.</p>${eq(String.raw`\begin{aligned}\operatorname{score}&=q_s^\top A(t-s)k_t,\quad A(0)=I\\A(a+b)&=A(a)A(b),\quad A(-a)=A(a)^{-1}\\A(t)&=\exp(tX),\quad X=A'(0)\end{aligned}`,'A is a representation of additive translations in invertible matrices. Continuous real positions give a one-parameter matrix group.')}
<p>Composition says that two small shifts produce the same map as their sum. X is the generator: a fixed rule for an infinitesimal change. The matrix exponential accumulates that rule over a finite displacement.</p><p>For integer positions alone, A(n)=A(1)ⁿ. A discrete invertible transition need not possess a real generator that extends it continuously. Real timestamps and learned effective time require the stronger continuous assumption.</p><p>Use one sign convention. Above ${inlineMath(String.raw`\Delta=t-s`)} is key minus query. For causal decay below, age ${inlineMath(String.raw`a=s-t\ge0`)} is query minus key. Replacing Δ with a negates the relevant generator; confusing them turns decay into growth.</p><details><summary>General query/key factorization</summary>${eq(String.raw`\begin{aligned}G(t)&=A(t),\quad F(s)=A(-s)^\top\\F(s)^\top G(t)&=A(-s)A(t)=A(t-s)\end{aligned}`,'For an arbitrary group, query and key transforms need not be the same. Orthogonal rotations allow the familiar shared Q/K transform.')}<p>Normalizing equal-position interaction to I assumes a nonsingular same-time operator. Singular transformations need a restricted-space treatment; a change of basis alone cannot make a singular matrix invertible.</p></details>${eq(String.raw`\mathcal P=\begin{bmatrix}A(0)&A(1)&A(2)\\A(-1)&A(0)&A(1)\\A(-2)&A(-1)&A(0)\end{bmatrix}`,"Rows are query positions s=0,1,2; columns are key positions t=0,1,2. Each entry is a matrix block A(t−s), not a scalar logit.")}<p>A Toeplitz-like operator table has the same A along each relative diagonal. Actual content logits need not be Toeplitz, because q and k vary with the tokens. A causal mask removes future-key entries above the diagonal without changing the algebraic group.</p>`)}
${section('generators','Read the generator, not only the name',`${table('Closed-form blocks under an age convention',['Generator X','A(a)=exp(aX)','Interpretation'],[[inlineMath(String.raw`0`),inlineMath(String.raw`I`),'Explicit position does nothing'],[inlineMath(String.raw`-\lambda I`),inlineMath(String.raw`e^{-\lambda a}I`),'Decay with positive age'],[inlineMath(String.raw`\begin{bmatrix}0&-\omega\\\omega&0\end{bmatrix}`),inlineMath(String.raw`R(\omega a)`),'Norm-preserving rotation'],[inlineMath(String.raw`-\lambda I+\begin{bmatrix}0&-\omega\\\omega&0\end{bmatrix}`),inlineMath(String.raw`e^{-\lambda a}R(\omega a)`),'Damped rotation'],[inlineMath(String.raw`N=\begin{bmatrix}0&1\\0&0\end{bmatrix},\quad N^2=0`),inlineMath(String.raw`I+aN=\begin{bmatrix}1&a\\0&1\end{bmatrix}`),"Shear: "+inlineMath(String.raw`[x,v]\mapsto[x+av,v]`)]])}
<p>A real scalar block gives exponential decay or growth. A complex conjugate eigenvalue pair ${inlineMath(String.raw`u\pm\mathrm{i}\omega`)} gives ${inlineMath(String.raw`e^{ua}`)} times a rotation after a fixed basis change. A nontrivial Jordan block adds a polynomial factor.</p>${eq(String.raw`\begin{aligned}X&=uI+N,\quad N^r=0\\\exp(aX)&=e^{ua}\sum_{j=0}^{r-1}\frac{a^jN^j}{j!}\end{aligned}`,'The nilpotent series terminates. X=0 supplies identity, not the nontrivial polynomial behavior of a defective zero-eigenvalue block.')}
${eq(String.raw`X_i=\begin{bmatrix}0&-\omega_i\\\omega_i&0\end{bmatrix},\qquad\operatorname{eig}(X_i)=\{+i\omega_i,-i\omega_i\}`,"Here i in ±iω is the imaginary unit; the subscript i indexes a rotary pair. Changing the RoPE spectrum changes these eigenfrequencies.")}<p>RoPE chooses imaginary frequencies. Partial RoPE combines rotation blocks with zero blocks. Retention can combine rotation and decay. Data-dependent gates can define effective elapsed time, but need not form one fixed content-independent generator family.</p>${eq(String.raw`X=0_{\mathrm{content}}\oplus X_{\mathrm{rotation}}\oplus X_{\mathrm{decay}}\oplus X_{\mathrm{Jordan}}`,"The direct sum allocates distinct feature subspaces. Exponentiate each block independently; no dense whole-head matrix exponential is required.")}<p>One head can preserve content in one subspace, rotate another, and decay a third. This is a design possibility, not a reported winning architecture. Pair or scalar formulas keep the operation linear in feature width.</p>${generatorLab}`)}
${section('alibi','Additive bias through augmented coordinates',`<p>ALiBi directly subtracts a per-head slope times causal age from a logit. That additive content-independent term is not a same-width linear transformation of arbitrary content Q/K.</p>${eq(String.raw`\begin{aligned}\ell_{ij}&=q_i^\top k_j-ma,\quad a=i-j\ge0\\N&=\begin{bmatrix}0&1\\0&0\end{bmatrix},\quad \bar q=\begin{bmatrix}1\\0\end{bmatrix},\quad\bar k=\begin{bmatrix}0\\-m\end{bmatrix}\\\bar q^\top e^{aN}\bar k&=[1,0]\begin{bmatrix}1&a\\0&1\end{bmatrix}\begin{bmatrix}0\\-m\end{bmatrix}=-ma\end{aligned}`,'Append the auxiliary two-dimensional channel to an identity-transformed content channel. The bias is reproduced by the resulting bilinear form.')}
<p>The construction connects additive linear bias to a unipotent group action. It is an explanation, not a recommendation to replace a cheap bias addition with dense matrix operations. Arbitrary relative-bias tables are not all generated by this construction.</p><p>The Jane Street article explains this restricted classification and its ALiBi addendum. GRAPE develops related group actions and learned subspaces beyond fixed RoPE coordinate pairs. The framework is useful for design; it does not establish a universal winning positional family.</p>`)}
${section('stability','Algebraic validity is not numerical stability',`<p>An invertible group can be stable in one direction and unstable in the other. A decaying age transform grows at negative age. Causal masking excludes future keys; bidirectional use requires a different stability argument.</p>${table('What the spectrum does and does not guarantee',['Structure','Behavior'],[['Positive real part','Exponential growth in positive time'],['Negative real part','Forward decay; inverse-direction growth'],['Pure imaginary, diagonalizable','Bounded oscillations in a fixed finite-dimensional basis'],['Skew-symmetric generator','Orthogonal rotations: exact Euclidean norm preservation'],['Nontrivial zero Jordan block','Polynomial growth despite zero real eigenvalues']])}
<p>A poorly conditioned change of basis can amplify norms or numerical error even when the spectrum appears benign. Pure imaginary eigenvalues alone do not guarantee orthogonal, unit-norm motion. Non-normal decaying systems can also show transient growth.</p><p>Parameterize small known blocks when possible. Direct rotation/decay/polynomial formulas can cost O(d); an arbitrary learned dense generator needs a more expensive exponential and a stability constraint.</p><p>The classification assumes linear feature maps, relative-shift consistency, continuity and invertibility on the represented space. Learned absolute embeddings, nonlinear mechanisms, arbitrary score biases, content-dependent operators and masks fall outside some assumptions. The result classifies a useful design space, not all imaginable positional encodings.</p>`)}
${section('practice','Ablate the positional contract',`<ol class="dense-checklist"><li>Identify whether the method acts on embeddings, Q/K, logits or recurrent state.</li><li>Specify positions, signed displacement, rotary width/pair layout and cache offsets.</li><li>Check norm/phase behavior, composition and precision over the intended distances.</li><li>Keep data, initialization, optimizer, tokens and attention span fixed in comparisons.</li><li>Compare full RoPE, pure NoPE, alternating layers and local-RoPE/global-NoPE ratios such as 1:1, 3:1 and 5:1.</li><li>Evaluate inside and beyond training length; measure both short-context recovery and long-context failures.</li></ol><p>Test multi-needle/passkey retrieval at several depths, distractor-heavy document QA, relative-order tasks and code with distant declarations. Inspect attention mass, entropy, sinks and recency by layer type. A single retrieval score cannot explain all failure modes.</p><p>Measure prefill throughput, latency and cache memory at actual serving lengths. Check document-isolated causal masks during packed training. NoPE does not excuse cross-document leakage; scaling does not excuse stale-key phases.</p><p><a href="${link('training/parallelism')}">Parallelism →</a> handles distributed long-context work. <a href="${link('models/attention')}">Attention →</a> separates operator, span and cache compression. Positional encoding changes how positions influence these operations, not every cost of using them.</p>`)}
${section('sources','Sources and connected notes',`<p>${[['https://arxiv.org/abs/1706.03762','Transformer, 2017'],['https://arxiv.org/abs/2104.09864','RoFormer, 2021'],['https://arxiv.org/abs/2108.12409','ALiBi, 2021'],['https://aclanthology.org/2022.findings-emnlp.99/','Causal NoPE, 2022'],['https://proceedings.neurips.cc/paper_files/paper/2023/hash/4e85362c02172c0c6567ce593122d31c-Abstract-Conference.html','Length generalization, 2023'],['https://arxiv.org/abs/2501.18795','RNoPE, 2025'],['https://arxiv.org/abs/2606.15378','Efficient/full-attention hybrids, 2026'],['https://blog.janestreet.com/using-group-theory-to-explore-positional-encodings-attention/','Translation-group derivation'],['https://arxiv.org/abs/2512.07805','GRAPE'],['https://arxiv.org/abs/2307.08621','RetNet']].map(([u,t])=>cite(u,t)).join(' · ')}</p><details><summary>Context extension and model recipes</summary><p>${['9675','9706','9708','9948','10122'].map(id=>cite('https://kexue.fm/archives/'+id,'Su Jianlin / '+id)).join(' · ')} · ${cite('https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook','Smol Training Playbook')} · ${cite('https://arxiv.org/abs/2607.02770','Gemma 4 report')}</p><p>Connected recipe sections: <a href="${link('training/frontier-recipes#llama')}">Llama 3 →</a> · <a href="${link('training/frontier-recipes#mai-recipe')}">MAI →</a> · <a href="${link('training/frontier-recipes#kimi')}">Kimi K3 →</a> · <a href="${link('models/compact-recipes#gemma-cache')}">Gemma cache →</a> · <a href="${link('training/practice#context-evidence')}">Context-training evidence →</a></p></details>`)}
`);}
positionMeta.searchText=positionReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountPosition(scope=document){mountTopic(scope,positionMeta.slug,article=>{
 const lab=article.querySelector('[data-rotation-lab]'),frequency=lab.querySelector('select'),slider=lab.querySelector('input');const draw=value=>{const shift=value/5,w=Number(frequency.value),f=shiftFrame(shift,w);lab.querySelector('svg').innerHTML=clockSvg(f);for(const [name,v]of [['shift',shift],['m',f.m],['n',f.n]])lab.querySelector(`[data-${name}]`).textContent=v.toFixed(1);lab.querySelector('[data-score]').textContent=f.score.toFixed(6);lab.querySelector('[data-rotation-caption]').textContent=`Relative phase ${(3*w).toFixed(3)} rad. Dot product stays cos(${(3*w).toFixed(3)}), despite the common shift.`;};rangePlayback(article,lab,draw,14000);frequency.addEventListener('input',()=>draw(Number(slider.value)));
 const spectrum=article.querySelector('[data-spectrum-lab]');spectrum.querySelector('select').addEventListener('input',e=>{spectrum.querySelector('tbody').innerHTML=spectrumRows(Number(e.target.value));});
 const block=article.querySelector('[data-generator-lab]'),kind=block.querySelector('select'),age=block.querySelector('input'),captions={identity:'Identity leaves the vector unchanged.',rotation:'Rotation preserves norm in both directions.',decay:'Positive age decays. Negative age grows because the inverse undoes decay.',damped:'Positive age rotates and decays; the inverse rotates back and grows.',jordan:'Shear maps [0,1] to [a,1]. Composition works, but the norm grows with |a|.'};const update=()=>{const a=Number(age.value),v=apply2(positionalBlock(kind.value,a),[0,1]);block.querySelector('[data-age]').textContent=a;block.querySelector('[data-block-output]').textContent=`[${v.map(x=>x.toFixed(3)).join(', ')}]`;block.querySelector('[data-block-norm]').textContent=Math.hypot(...v).toFixed(3);block.querySelector('[data-block-caption]').textContent=captions[kind.value];};for(const control of [kind,age])control.addEventListener('input',update);update();
});}
